var TOTAL_SCORE_KEY = 'tetris_total_score';

// ===== ОЖИДАНИЕ ИНИЦИАЛИЗАЦИИ OK =====
var okInitPromise = null;
var okInitResolve = null;
// ===== OK STORAGE ДЛЯ ЗВЁЗД (ОБЩИЙ СЧЁТ) =====
