// ===== КОНФИГУРАЦИЯ =====
var APP_ID = 54620141;
var ACCESS_TOKEN = '2238166b2238166b2238166b2021797986222382238166b4826d211f79d2796efcd8994';

// ----- Переменные для VK -----
var vkInitialized = false;
