// Получение токена пользователя (только для VK)
function getUserAccessToken() {
  var platform = getPlatform();
  if (platform === 'ok') {
    // Для OK токен не нужен
    vkUserToken = null;
    window.vkUserToken = null;
    return Promise.resolve(null);
  }
  // VK
  return vkBridge.send('VKWebAppGetAuthToken', {
    app_id: APP_ID,
    scope: ''
  })
  .then(function(data) {
    vkUserToken = data.access_token;
    window.vkUserToken = vkUserToken;
    if (data.user_id && !window.vkUserId) {
      window.vkUserId = data.user_id;
    }
    return vkUserToken;
  })
  .catch(function(err) {
    console.error('[VK] Ошибка получения токена:', err);
    vkUserToken = null;
    window.vkUserToken = null;
    return null;
  });
}

// ===== ИНИЦИАЛИЗАЦИЯ =====
export var initYandexSdk = function() {
    // ---- для ок----
  if (typeof vkBridge !== 'undefined') {
    window.vkBridge = vkBridge;
  }
  //____________________________________________
  return new Promise(function(resolve) {
    var platform = getPlatform();

    // ----- ОДНОКЛАССНИКИ -----
if (platform === 'ok') {
  var okResolved = false;
  var originalResolve = resolve;

  // Переопределяем resolve, чтобы он срабатывал только один раз
  resolve = function(value) {
    if (!okResolved) {
      okResolved = true;
      originalResolve(value);
    }
  };

  // Таймаут на случай, если инициализация не завершится через 3 секунды
  setTimeout(function() {
    if (!okResolved) {
      console.warn('⚠️ OK инициализация по таймауту');
      okResolved = true;
      // Устанавливаем минимальные флаги вручную
      if (typeof okInitialized !== 'undefined') okInitialized = true;
      if (!window.okUserId) {
        window.okUserId = 'ok_guest';
      }
      if (!window.okUserLang) {
        window.okUserLang = 'ru';
      }
      var ysdkInstance = {
        platform: 'ok',
        userId: window.okUserId,
        lang: window.okUserLang,
        bridge: typeof vkBridge !== 'undefined' ? vkBridge : null
      };
      originalResolve(ysdkInstance);
    }
  }, 3000);

  // Существующая логика инициализации
  if (typeof vkBridge !== 'undefined') {
    vkBridge.send('VKWebAppInit')
      .then(function() {
        console.log('✅ VK Bridge инициализирован для OK');
        loadFapiAndFinish(resolve);
      })
      .catch(function(err) {
        console.error('❌ Ошибка инициализации VK Bridge в OK:', err);
        loadFapiAndFinish(resolve);
      });
  } else {
    console.warn('⚠️ VK Bridge не найден в OK');
    loadFapiAndFinish(resolve);
  }
  return;
}

    // ----- ВКОНТАКТЕ (существующий код) -----
    if (typeof vkBridge === 'undefined') {
      console.warn('VK Bridge не обнаружен');
      resolve(null);
      return;
    }
    window.vkBridge = vkBridge;

    vkBridge.send('VKWebAppInit')
      .then(function() {
        vkInitialized = true;
        return vkBridge.send('VKWebAppGetLaunchParams');
      })
      .then(function(launchParams) {
        var vkUserId = launchParams.vk_user_id;
        var vkOriginalId = launchParams.vk_original_vk_id;
        var vkOkUserId = launchParams.vk_ok_user_id;
        
        window.vkUserIdForLeaderboard = vkUserId || vkOriginalId;
        window.vkUserId = vkOriginalId || vkUserId || vkOkUserId;
        window.vkUserLang = launchParams.vk_language || launchParams.language || 'ru';
        
        try {
          var constModule = require('./const');
          constModule.changeLanguageFromVK(window.vkUserLang);
        } catch(e) {
          console.warn('Не удалось применить язык:', e);
        }
        return Promise.resolve();
      })
      .then(function() {
        if (!window.vkUserId) {
          var savedId = localStorage.getItem('vk_user_id');
          if (savedId) {
            window.vkUserId = savedId;
          }
        }
        window.vkUserToken = vkUserToken;
        window.vkInitialized = true;
        localStorage.setItem('vk_initialized', 'true');
        ysdkInstance = { 
          bridge: vkBridge, 
          userId: window.vkUserId, 
          token: window.vkUserToken, 
          lang: window.vkUserLang 
        };
        preloadRewardedAd();
        resolve(ysdkInstance);
      })
      .catch(function(err) {
        console.error('Ошибка инициализации VK Bridge:', err);
        if (!window.vkUserId) {
          var savedId = localStorage.getItem('vk_user_id');
          if (savedId) {
            window.vkUserId = savedId;
            window.vkInitialized = true;
          }
        }
        ysdkInstance = { bridge: vkBridge, userId: window.vkUserId, token: null, lang: 'ru' };
        resolve(ysdkInstance);
      });
  });
};


// ----- Вспомогательная функция для завершения инициализации OK -----
function loadFapiAndFinish(resolve) {
  if (typeof FAPI === 'undefined') {
    var script = document.createElement('script');
    script.src = '//api.ok.ru/js/fapi5.js';
    script.defer = true;
    script.onload = function() {
      finishOkInit(resolve);
    };
    script.onerror = function() {
      console.error('❌ Не удалось загрузить OK SDK (fapi5.js)');
      finishOkInit(resolve);
    };
    document.head.appendChild(script);
  } else {
    finishOkInit(resolve);
  }
}

function finishOkInit(resolve) {
  if (typeof FAPI !== 'undefined') {
    try {
      var params = FAPI.Util.getRequestParameters();
      window.okUserId = params.logged_user_id || params.user_stat_id || null;
      window.okUserLang = params.language || 'ru';
    } catch (e) {
      console.warn('⚠️ Ошибка получения параметров FAPI:', e);
    }
  }

  if (!window.okUserId && typeof vkBridge !== 'undefined') {
    vkBridge.send('VKWebAppGetLaunchParams')
      .then(function(params) {
        window.okUserId = params.vk_user_id || params.vk_original_vk_id || params.vk_ok_user_id || null;
        window.okUserLang = params.vk_language || params.language || 'ru';
        okInitialized = true;
        // Уведомляем ожидающие вызовы
if (okInitResolve) {
  okInitResolve();
  okInitResolve = null;
  okInitPromise = null;
}
        applyOkLanguage();
        ysdkInstance = { 
          platform: 'ok', 
          userId: window.okUserId, 
          lang: window.okUserLang, 
          bridge: vkBridge 
        };
        console.log('✅ OK инициализирован (ID из VK Bridge):', window.okUserId);
        resolve(ysdkInstance);
      })
      .catch(function(err) {
        console.error('❌ Ошибка VKWebAppGetLaunchParams в ОК:', err);
        okInitialized = true;
        // Уведомляем ожидающие вызовы
if (okInitResolve) {
  okInitResolve();
  okInitResolve = null;
  okInitPromise = null;
}
        ysdkInstance = { 
          platform: 'ok', 
          userId: window.okUserId, 
          lang: window.okUserLang || 'ru', 
          bridge: vkBridge 
        };
        resolve(ysdkInstance);
      });
  } else {
    okInitialized = true;
    // Уведомляем ожидающие вызовы
if (okInitResolve) {
  okInitResolve();
  okInitResolve = null;
  okInitPromise = null;
}
    applyOkLanguage();
    ysdkInstance = { 
      platform: 'ok', 
      userId: window.okUserId, 
      lang: window.okUserLang || 'ru', 
      bridge: vkBridge 
    };
    console.log('✅ OK инициализирован (ID из FAPI):', window.okUserId);
    resolve(ysdkInstance);
  }
}

function applyOkLanguage() {
  try {
    var constModule = require('./const');
    constModule.changeLanguageFromVK(window.okUserLang);
  } catch(e) {}
}

// ===== ОПРЕДЕЛЕНИЕ ПЛАТФОРМЫ =====
var PLATFORM = null;
function getPlatform() {
  if (PLATFORM) return PLATFORM;
  var urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('vk_client') === 'ok') {
    PLATFORM = 'ok';
    return PLATFORM;
  }
  var ua = navigator.userAgent;
  if (ua.indexOf('Odnoklassniki') !== -1 || ua.indexOf('OKApp') !== -1) {
    PLATFORM = 'ok';
    return PLATFORM;
  }
  var hostname = window.location.hostname;
  if (hostname.indexOf('ok.ru') !== -1 || hostname.indexOf('odnoklassniki') !== -1) {
    PLATFORM = 'ok';
    return PLATFORM;
  }
  PLATFORM = 'vk';
  return PLATFORM;
}

function logPlatform() {
  console.log('🎮 Платформа:', getPlatform());
}

// ===== OK STORAGE (только через FAPI) =====
function loadOKScore() {
  return new Promise(function(resolve) {
    if (!okInitialized) {
      if (!okInitPromise) {
        okInitPromise = new Promise(function(res) {
          okInitResolve = res;
        });
      }
      okInitPromise.then(function() {
        loadOKScore().then(resolve);
      });
      return;
    }
    if (typeof FAPI === 'undefined') {
      resolve(0);
      return;
    }
    FAPI.invokeMethod('storage.get', {
      key: OK_STORAGE_KEY
    }, function(data) {
      var score = parseInt(data.value, 10) || 0;
      resolve(score);
    }, function(error) {
      console.error('❌ OK storage.get ошибка:', error);
      resolve(0);
    });
  });
}

function saveOKScore(score) {
  return new Promise(function(resolve) {
    if (typeof FAPI === 'undefined' || !okInitialized) {
      resolve(false);
      return;
    }
    loadOKScore().then(function(current) {
      if (score <= current) {
        resolve(false);
        return;
      }
      FAPI.invokeMethod('storage.set', {
        key: OK_STORAGE_KEY,
        value: String(score)
      }, function() {
        resolve(true);
      }, function(error) {
        console.error('❌ OK storage.set ошибка:', error);
        resolve(false);
      });
    });
  });
}

// ===== ЗАГРУЗКА РЕКОРДА =====
export var loadYandexHighScore = function(storeInstance) {
  var platform = getPlatform();

  // ----- ОК -----
  if (platform === 'ok') {
    loadOKScore().then(function(score) {
      if (score > 0) {
        var currentMax = 0;
        try {
          currentMax = storeInstance.getState().get('max') || 0;
        } catch(e) {}
        if (score > currentMax) {
          storeInstance.dispatch(actions.max(score));
          localStorage.setItem('tetris_high_score', String(score));
          localStorage.setItem('tetris_max_sync', String(score));
          console.log('✅ OK рекорд загружен и обновлён:', score);
        } else if (score > 0 && currentMax === 0) {
          storeInstance.dispatch(actions.max(score));
          localStorage.setItem('tetris_high_score', String(score));
          localStorage.setItem('tetris_max_sync', String(score));
          console.log('✅ OK рекорд установлен из хранилища:', score);
        }
      }
    });
    return;
  }

  // ----- VK (без Cloudflare) -----
  var userIdForVK = window.vkUserIdForLeaderboard || window.vkUserId;
  
  // Читаем локальный рекорд
  var localScore = 0;
  try {
    var savedData = localStorage.getItem('REACT_TETRIS');
    if (savedData) {
      var parsed = JSON.parse(atob(decodeURIComponent(savedData)));
      localScore = parsed.max || 0;
    }
  } catch(e) {
    try {
      localScore = parseInt(localStorage.getItem('tetris_high_score'), 10) || 0;
    } catch(e2) {}
  }
  
  var vkStorageScore = 0;
  var tasksToWait = 0;
  
  var finalizeAndSync = function() {
    // Берем максимум из локального и VK Storage
    var absoluteMax = Math.max(localScore, vkStorageScore);
    
    var currentMax = 0;
    try {
      currentMax = storeInstance.getState().get('max') || 0;
    } catch(e) {}
    
    if (absoluteMax > currentMax) {
      storeInstance.dispatch(actions.max(absoluteMax));
      localStorage.setItem('tetris_high_score', String(absoluteMax));
      localStorage.setItem('tetris_max_sync', String(absoluteMax));
      if (window.vkUserId) {
        localStorage.setItem('vk_user_id', window.vkUserId);
      }
    } else if (absoluteMax > 0 && currentMax !== absoluteMax) {
      storeInstance.dispatch(actions.max(absoluteMax));
      localStorage.setItem('tetris_high_score', String(absoluteMax));
      localStorage.setItem('tetris_max_sync', String(absoluteMax));
    }
    
    // Синхронизация VK Storage, если локальный рекорд больше
    if (platform === 'vk' && typeof vkBridge !== 'undefined' && userIdForVK) {
      if (vkStorageScore === 0 && localScore > 0) {
        vkBridge.send('VKWebAppStorageSet', {
          key: CLOUD_STORAGE_KEY,
          value: String(localScore)
        }).catch(function(err) { console.error('Ошибка принудительного сохранения VK Storage:', err); });
      }
      
      if (localScore > vkStorageScore && localScore > 0) {
        vkBridge.send('VKWebAppStorageSet', {
          key: CLOUD_STORAGE_KEY,
          value: String(localScore)
        }).catch(function(err) { console.error('Ошибка VK Storage (локальный рекорд):', err); });
      }
    }
    
    // Обновление таблицы лидеров (если рекорд побит)
    if (platform === 'vk' && vkInitialized && userIdForVK && vkUserToken && absoluteMax > 0) {
      vkBridge.send('VKWebAppCallAPIMethod', {
        method: 'secure.addAppEvent',
        request_id: 'syncScore_' + Date.now(),
        params: {
          client_secret: 'Q5I9iCJXGWiwYDb8aaHr',
          user_id: userIdForVK,
          activity_id: 2,
          value: absoluteMax,
          v: '5.131',
          global: 1,
          access_token: ACCESS_TOKEN
        }
      })
      .then(function() { console.log('✅ Таблица лидеров обновлена'); })
      .catch(function(err) { console.error('Ошибка таблицы лидеров:', err); });
    }
  };
  
  var checkAndFinalize = function() {
    tasksToWait--;
    if (tasksToWait === 0) {
      finalizeAndSync();
    }
  };
  
  // Загружаем из VK Storage
  if (platform === 'vk' && typeof vkBridge !== 'undefined') {
    tasksToWait++;
    vkBridge.send('VKWebAppStorageGet', { keys: [CLOUD_STORAGE_KEY] })
      .then(function(data) {
        var score = 0;
        if (data && data.keys) {
          if (Array.isArray(data.keys)) {
            if (data.keys.length > 0 && data.keys[0].value !== undefined) {
              score = parseInt(data.keys[0].value, 10) || 0;
            }
          } else if (typeof data.keys === 'object' && data.keys !== null) {
            if (data.keys.value !== undefined) {
              score = parseInt(data.keys.value, 10) || 0;
            } else if (data.keys[CLOUD_STORAGE_KEY] !== undefined) {
              score = parseInt(data.keys[CLOUD_STORAGE_KEY], 10) || 0;
            }
          } else if (data.response) {
            if (Array.isArray(data.response) && data.response.length > 0) {
              score = parseInt(data.response[0], 10) || 0;
            }
          }
        }
        vkStorageScore = score;
        var currentMax = 0;
        try {
          currentMax = storeInstance.getState().get('max') || 0;
        } catch(e) {}
        if (vkStorageScore > currentMax) {
          storeInstance.dispatch(actions.max(vkStorageScore));
          localStorage.setItem('tetris_high_score', String(vkStorageScore));
          localStorage.setItem('tetris_max_sync', String(vkStorageScore));
        } else if (vkStorageScore > 0 && currentMax === 0) {
          storeInstance.dispatch(actions.max(vkStorageScore));
          localStorage.setItem('tetris_high_score', String(vkStorageScore));
          localStorage.setItem('tetris_max_sync', String(vkStorageScore));
        }
        checkAndFinalize();
      })
      .catch(function(err) {
        console.error('Ошибка загрузки VK Storage:', err);
        vkStorageScore = 0;
        checkAndFinalize();
      });
  }
  
  if (tasksToWait === 0) {
    finalizeAndSync();
  }
};

// ===== СОХРАНЕНИЕ РЕКОРДА =====
export var saveYandexScore = function(scoreValue) {
  var platform = getPlatform();
  var currentScore = parseInt(scoreValue, 10) || 0;
  if (currentScore <= 0) return;

  // ----- ОК -----
  if (platform === 'ok') {
    saveOKScore(currentScore).then(function(success) {
      if (success) {
        localStorage.setItem('tetris_high_score', String(currentScore));
        localStorage.setItem('tetris_max_sync', String(currentScore));
        store.dispatch(actions.max(currentScore));
        console.log('✅ OK рекорд сохранён:', currentScore);
      } else {
        loadOKScore().then(function(existing) {
          var localMax = 0;
          try {
            localMax = store.getState().get('max') || 0;
          } catch(e) {}
          if (existing > localMax) {
            store.dispatch(actions.max(existing));
            localStorage.setItem('tetris_high_score', String(existing));
            localStorage.setItem('tetris_max_sync', String(existing));
          }
        });
      }
    });
    return;
  }

  // ----- VK (без Cloudflare) -----
  var effectiveUserId = window.vkUserIdForLeaderboard || window.vkUserId;
  var bridge = typeof vkBridge !== 'undefined' ? vkBridge : window.vkBridge;
  
  if (platform === 'vk' && bridge && effectiveUserId) {
    bridge.send('VKWebAppStorageGet', { keys: [CLOUD_STORAGE_KEY] })
      .then(function(data) {
        var existingScore = 0;
        if (data && data.keys) {
          if (Array.isArray(data.keys)) {
            if (data.keys.length > 0 && data.keys[0].value !== undefined) {
              existingScore = parseInt(data.keys[0].value, 10) || 0;
            }
          } else if (typeof data.keys === 'object' && data.keys !== null) {
            if (data.keys.value !== undefined) {
              existingScore = parseInt(data.keys.value, 10) || 0;
            } else if (data.keys[CLOUD_STORAGE_KEY] !== undefined) {
              existingScore = parseInt(data.keys[CLOUD_STORAGE_KEY], 10) || 0;
            }
          } else if (data.response) {
            if (Array.isArray(data.response) && data.response.length > 0) {
              existingScore = parseInt(data.response[0], 10) || 0;
            }
          }
        }
        
        if (currentScore > existingScore) {
          localStorage.setItem('tetris_high_score', String(currentScore));
          localStorage.setItem('tetris_max_sync', String(currentScore));
          store.dispatch(actions.max(currentScore));
          
          // Сохраняем в VK Storage
          bridge.send('VKWebAppStorageSet', {
            key: CLOUD_STORAGE_KEY,
            value: String(currentScore)
          })
          .catch(function(err) { console.warn('Ошибка VK Storage (bridge):', err); });
          
          // Обновляем таблицу лидеров
          if (bridge && vkInitialized && effectiveUserId) {
            bridge.send('VKWebAppCallAPIMethod', {
              method: 'secure.addAppEvent',
              request_id: 'addScore_' + Date.now(),
              params: {
                client_secret: 'Q5I9iCJXGWiwYDb8aaHr',
                user_id: effectiveUserId,
                activity_id: 2,
                value: currentScore,
                v: '5.131',
                global: 1,
                access_token: ACCESS_TOKEN
              }
            })
            .catch(function(err) { console.error('Ошибка таблицы лидеров:', err); });
          }
        } else {
          var localMax = 0;
          try {
            localMax = store.getState().get('max') || 0;
          } catch(e) {}
          if (existingScore > localMax) {
            store.dispatch(actions.max(existingScore));
            localStorage.setItem('tetris_high_score', String(existingScore));
            localStorage.setItem('tetris_max_sync', String(existingScore));
          }
        }
      })
      .catch(function(err) {
        console.warn('Ошибка проверки VK Storage:', err);
        localStorage.setItem('tetris_high_score', String(currentScore));
        localStorage.setItem('tetris_max_sync', String(currentScore));
        store.dispatch(actions.max(currentScore));
      });
  } else {
    localStorage.setItem('tetris_high_score', String(currentScore));
    localStorage.setItem('tetris_max_sync', String(currentScore));
    store.dispatch(actions.max(currentScore));
  }
};

