export var preloadRewardedAd = function() {
  var platform = getPlatform();
  
  // ----- ОК: предзагрузка через VK Bridge -----
  if (platform === 'ok') {
    if (typeof vkBridge === 'undefined') return;
    vkBridge.send('VKWebAppCheckNativeAds', { ad_format: 'reward' })
      .then(function(data) {
        if (data && data.result) {
          console.log('✅ OK: рекламные материалы для reward предзагружены');
        }
      })
      .catch(function(err) {
        console.warn('❌ OK: ошибка предзагрузки рекламы:', err);
      });
    return;
  }

  // ----- VK -----
  if (typeof vkBridge === 'undefined') {
    console.log('ℹ️ VK Bridge не найден, предзагрузка невозможна');
    return;
  }
  if (!vkInitialized) {
    console.log('ℹ️ VK не инициализирован, предзагрузка отложена');
    return;
  }
  vkBridge.send('VKWebAppCheckNativeAds', { ad_format: 'reward' })
    .then(function(data) {
      if (data && data.result) {
        console.log('✅ Рекламные материалы для reward предзагружены');
      } else {
        console.log('⚠️ Рекламные материалы не найдены, запрос отправлен');
      }
    })
    .catch(function(err) {
      console.warn('❌ Ошибка предзагрузки рекламы:', err);
    });
};

export var showRewardedAd = function() {
  return new Promise(function(resolve) {
    var platform = getPlatform();
    
    // ----- ОК: реклама за вознаграждение через VK Bridge -----
    if (platform === 'ok') {
      if (typeof vkBridge === 'undefined') {
        resolve(false);
        return;
      }
      vkBridge.send('VKWebAppShowNativeAds', { ad_format: 'reward' })
        .then(function(data) {
          if (data && data.result === true) {
            console.log('✅ OK: реклама за вознаграждение успешно показана');
            preloadRewardedAd();
            resolve(true);
          } else {
            console.log('⚠️ OK: реклама не была показана');
            resolve(false);
          }
        })
        .catch(function(error) {
          console.error('❌ OK: ошибка при показе рекламы:', error);
          resolve(false);
        });
      return;
    }

    // ----- VK -----
    if (typeof vkBridge === 'undefined') {
      console.log("ℹ️ VK Bridge не найден");
      resolve(false);
      return;
    }
    if (!vkInitialized) {
      console.log("ℹ️ VK не инициализирован");
      resolve(false);
      return;
    }
    vkBridge.send('VKWebAppShowNativeAds', { ad_format: 'reward' })
      .then(function(data) {
        if (data && data.result === true) {
          console.log('✅ Реклама за вознаграждение успешно показана');
          preloadRewardedAd();
          resolve(true);
        } else {
          console.log('⚠️ Реклама не была показана');
          resolve(false);
        }
      })
      .catch(function(error) {
        console.error('❌ Ошибка при показе рекламы:', error);
        resolve(false);
      });
  });
};



function loadOKTotalScore() {
  return new Promise(function(resolve) {
    if (!okInitialized) {
      if (!okInitPromise) {
        okInitPromise = new Promise(function(res) {
          okInitResolve = res;
        });
      }
      okInitPromise.then(function() {
        loadOKTotalScore().then(resolve);
      });
      return;
    }
    if (typeof FAPI === 'undefined') {
      resolve(0);
      return;
    }
    FAPI.invokeMethod('storage.get', {
      key: OK_TOTAL_SCORE_KEY
    }, function(data) {
      var score = parseInt(data.value, 10) || 0;
      resolve(score);
    }, function(error) {
      console.error('❌ OK storage.get (звезды) ошибка:', error);
      resolve(0);
    });
  });
}

function saveOKTotalScore(score) {
  return new Promise(function(resolve) {
    if (typeof FAPI === 'undefined' || !okInitialized) {
      resolve(false);
      return;
    }
    // Проверяем текущее значение, чтобы не перезаписать меньшим
    loadOKTotalScore().then(function(current) {
      if (score <= current) {
        resolve(false);
        return;
      }
      FAPI.invokeMethod('storage.set', {
        key: OK_TOTAL_SCORE_KEY,
        value: String(score)
      }, function() {
        resolve(true);
      }, function(error) {
        console.error('❌ OK storage.set (звезды) ошибка:', error);
        resolve(false);
      });
    });
  });
}

