// src/storagePatch.js
// Должен быть импортирован самым первым в index.js

function getPlatform() {
  // Копия функции из yandexSdk.js (без импорта, чтобы не вызывать его до переопределения)
  if (typeof window === 'undefined') return 'vk';
  var urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('vk_client') === 'ok') {
    return 'ok';
  }
  var ua = navigator.userAgent;
  if (ua.indexOf('Odnoklassniki') !== -1 || ua.indexOf('OKApp') !== -1) {
    return 'ok';
  }
  var hostname = window.location.hostname;
  if (hostname.indexOf('ok.ru') !== -1 || hostname.indexOf('odnoklassniki') !== -1) {
    return 'ok';
  }
  return 'vk';
}

var platform = getPlatform();

if (platform === 'ok') {
  var original = window.localStorage;
  var prefix = 'ok_';

  function getActualKey(key) {
    // Если ключ уже начинается с 'ok_', не добавляем префикс (используется для OK-специфичных ключей)
    if (key && key.startsWith('ok_')) {
      return key;
    }
    return prefix + key;
  }

  var wrapped = {
    getItem: function(key) {
      return original.getItem(getActualKey(key));
    },
    setItem: function(key, value) {
      return original.setItem(getActualKey(key), value);
    },
    removeItem: function(key) {
      return original.removeItem(getActualKey(key));
    },
    clear: function() {
      // Удаляем только ключи с префиксом, чтобы не задеть другие
      var keysToRemove = [];
      for (var i = 0; i < original.length; i++) {
        var key = original.key(i);
        if (key && key.startsWith(prefix)) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach(function(key) {
        original.removeItem(key);
      });
    },
    get length() {
      var count = 0;
      for (var i = 0; i < original.length; i++) {
        var key = original.key(i);
        if (key && key.startsWith(prefix)) {
          count++;
        }
      }
      return count;
    },
    key: function(index) {
      var count = 0;
      for (var i = 0; i < original.length; i++) {
        var key = original.key(i);
        if (key && key.startsWith(prefix)) {
          if (count === index) return key;
          count++;
        }
      }
      return null;
    }
  };

  window.localStorage = wrapped;
}


